begin;set local statement_timeout='30s';
create temporary table training_fixture(k text primary key,v uuid);
insert into training_fixture select k,gen_random_uuid() from unnest(array['user','business','foreign','key']) k;
do $$ begin execute format('grant usage on schema %I to authenticated,anon',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end $$;
grant select on training_fixture to authenticated,anon;
insert into auth.users(id,aud,role,email) select v,'authenticated','authenticated',v::text||'@example.invalid' from training_fixture where k='user';
insert into public.restaurants(id,name,slug) select v,'Training test',v::text from training_fixture where k in('business','foreign');
insert into public.restaurant_members(restaurant_id,user_id,role) values((select v from training_fixture where k='business'),(select v from training_fixture where k='user'),'owner');
select set_config('request.jwt.claim.sub',(select v::text from training_fixture where k='user'),true);set local role authenticated;
do $$ declare r uuid:=(select v from training_fixture where k='business');key uuid:=(select v from training_fixture where k='key');job jsonb;again jsonb;rid uuid;question jsonb:='[{"question":"hola","expected_answer":"saludo","category":"saludos"},{"question":"precio","expected_answer":"precio guardado","category":"precios"}]';begin
 job=public.kb_start_training(r,key,'{"knowledge":{}}',question);rid=(job->>'id')::uuid;
 if (select count(*) from public.training_results where run_id=rid)<>2 then raise exception 'Question batch missing';end if;
 again=public.kb_start_training(r,key,'{}',question);if again->>'id'<>job->>'id' then raise exception 'Idempotency failed';end if;
 begin perform public.kb_start_training(r,gen_random_uuid(),'{}',question);raise exception 'Parallel batch allowed';exception when raise_exception then if sqlerrm<>'Active batch' then raise;end if;end;
 if public.kb_claim_training(r,rid,1) is distinct from true then raise exception 'First claim denied';end if;
 if public.kb_claim_training(r,rid,1) is distinct from false or public.kb_claim_training(r,rid,2) is distinct from false then raise exception 'Duplicate or concurrent claim';end if;
 perform public.kb_finish_training(r,rid,1,'{"answer":"hola","provider":"structured","model":null,"verdict":"review","error_code":null,"reason":"Pendiente","latency_ms":1}');
 if public.kb_claim_training(r,rid,2) is distinct from true then raise exception 'Second claim denied';end if;
 perform public.kb_finish_training(r,rid,2,'{"answer":"precio","provider":"structured","model":null,"verdict":"review","error_code":null,"reason":"Pendiente","latency_ms":1}');
 if (select status from public.training_runs where id=rid)<>'completed' then raise exception 'Run not completed';end if;
 if exists(select 1 from public.training_results where run_id=rid and verdict<>'review') then raise exception 'Auto approval';end if;
 begin update public.training_runs set knowledge_snapshot='{"changed":true}' where id=rid;raise exception 'Snapshot modified';exception when check_violation then null;end;
 begin perform public.kb_start_training((select v from training_fixture where k='foreign'),gen_random_uuid(),'{}',question);raise exception 'Foreign batch allowed';exception when insufficient_privilege then null;end;
end $$;
reset role;set local role anon;
do $$ begin begin perform public.kb_start_training((select v from training_fixture where k='business'),gen_random_uuid(),'{}','[{"question":"hola"}]');raise exception 'Anonymous allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: 10 training checks; synthetic data rolled back' as result;
rollback;
